 * Copyright (c) 2026 pka_human (pka_human@proton.me)
 *
 * Symbol versions of libspingalett.so (ELF platforms): the functions the public headers declare, the
 * library's ABI. A node, once released, never changes; a 1.x release that adds functions lists them
 * in a node of its own (SPINGALETT_1.1 { global: ...; } SPINGALETT_1.0;), so that a program built
 * against it names the version it needs and the loader refuses an older library. Everything else
 * stays local. Tests/check_abi.py checks that these are the headers' functions, and on Linux that
 * they are what the library exports.
 */
SPINGALETT_1.0 {
    global:
        spingalett_activate;
        spingalett_append_layer;
        spingalett_clear_error;
